// Pull name, phone and message out of the Tally submission.
// Field labels in Tally should contain the words: Name, Phone, Message.
const body = $input.first().json.body || {};
const fields = (body.data && body.data.fields) || [];
const get = (word) => {
  const f = fields.find(x => String(x.label || '').toLowerCase().includes(word));
  return f ? String(f.value ?? '').trim() : '';
};

const name = get('name');
const message = get('message');
let phone = get('phone').replace(/[^\d+]/g, '');
if (!phone) throw new Error('No phone number in the form submission');
if (!phone.startsWith('+')) phone = '+' + phone;

const store = $getWorkflowStaticData('global');
store.convos = store.convos || {};
store.convos[phone] = {
  name,
  status: 'active',
  history: [{
    role: 'user',
    content: `New lead from the website form. Name: ${name || 'unknown'}. Message: ${message || '(no message)'}`
  }]
};

return [{ json: { phone, messages: store.convos[phone].history } }];

// Twilio sends From like 'whatsapp:+2348012345678' and the text in Body.
const b = $input.first().json.body || {};
const phone = String(b.From || '').replace('whatsapp:', '');
const text = String(b.Body || '').trim();
if (!phone || !text) return [];

const store = $getWorkflowStaticData('global');
store.convos = store.convos || {};
let convo = store.convos[phone];
if (!convo) {
  convo = { name: '', status: 'active', history: [] };
  store.convos[phone] = convo;
}

// Already opted out: send nothing.
if (convo.status === 'stopped') return [];

// Opt-out words: reply once, then stop for good.
if (/^(stop|unsubscribe|wrong number|cancel|end|quit)$/i.test(text)) {
  convo.status = 'stopped';
  return [{ json: { action: 'stop', phone, reply: "Understood, you won't hear from us again." } }];
}

convo.history.push({ role: 'user', content: text });
return [{ json: { action: 'ai', phone, messages: convo.history } }];

// Edit the assistant's instructions and listing sheet here.
const SYSTEM_PROMPT = `You are Sage, the text assistant for Jordan Reed at Demo Realty in Austin, Texas. A new lead just asked about a home. Your job: reply fast, be warm, learn their budget, timeline, area and must-haves, then offer a short call with Jordan.

Style:
- Text like a friendly human assistant. Max 2 short sentences per message. No emojis. Don't use exclamation marks in every line.
- Ask one question at a time.
- Sometimes mirror one key detail back so they feel heard, but don't start every message with it, and never say "got it" twice in a row.

Rules you never break:
- Only state facts that are in the listing sheet below. If you don't know, say "Let me check with Jordan and get right back to you."
- Never promise a price, discount, availability, approval, or legal or financial advice.
- Fair housing: never describe or steer by race, religion, national origin, sex, disability, family status or similar. Don't call an area "safe", "good for families" or rate schools. Instead, suggest they check public sources or ask Jordan.
- If they ask whether you are a bot or AI, say yes, honestly: "I'm an AI assistant for Jordan. Happy to get them on the phone."
- When they agree to a call, send this link: calendly.com/demo-realty/15min and say Jordan will be on it.
- The first message in the conversation is a form submission. Reply to it as the opening text message to that lead, using their first name.

Reply only with the text message itself, nothing else.

LISTING SHEET - DEMO REALTY (Austin, TX)
1) 12 Maple Street: $395,000. 3 bed / 2 bath, 1,650 sq ft. Fenced backyard: yes. Pets: dogs and cats allowed. Status: available. Showings Mon-Sat 10am-6pm. Updated kitchen, 2-car garage, 15 min to downtown.
2) 48 Oak Ridge Drive: $520,000. 4 bed / 3 bath, 2,300 sq ft. Fenced backyard: yes. Pets: yes. Status: available. Showings by appointment. Home office, pool, corner lot.
3) 7 Cedar Lane, Unit 4: $289,000. 2 bed / 2 bath condo, 1,050 sq ft. No private yard (shared courtyard). Pets: cats only, max 1. Status: under contract, backup offers accepted. HOA $280/month, gym and pool access.`;

const { phone, messages } = $input.first().json;

return [{
  json: {
    phone,
    body: {
      model: 'claude-opus-5-5',
      max_tokens: 2000,
      output_config: { effort: 'low' },
      fallbacks: 'default',
      system: SYSTEM_PROMPT,
      messages
    }
  }
}];

// Take the text reply out of Claude's response and save it to the conversation.
const res = $input.first().json;
const phone = $('Prepare Claude request').first().json.phone;
const FALLBACK = 'Let me check with Jordan and get right back to you.';

let reply = '';
if (res.stop_reason !== 'refusal') {
  reply = (res.content || [])
    .filter(b => b.type === 'text')
    .map(b => b.text)
    .join('')
    .trim();
}

const store = $getWorkflowStaticData('global');
const convo = store.convos && store.convos[phone];
if (convo) {
  // Save Claude's full content (including thinking blocks) unchanged, so later turns stay valid.
  if (reply) {
    convo.history.push({ role: 'assistant', content: res.content });
  } else {
    convo.history.push({ role: 'assistant', content: FALLBACK });
  }
}

return [{ json: { phone, reply: reply || FALLBACK } }];
